sql:
SELECT Branch, SUM(TotalSale_FCFA) AS total
FROM sales
GROUP BY Branch;

SELECT Category, AVG(UnitPrice_FCFA) AS avg_price
FROM sales
GROUP BY Category;

SELECT s.Product, b.City
FROM sales s
JOIN branches b ON s.Branch = b.Branch;

WITH t AS (
    SELECT Branch, SUM(Quantity) AS qty FROM sales GROUP BY Branch
)
SELECT * FROM t WHERE qty > 500;

SELECT CustomerType, ROUND(AVG(TotalSale_FCFA), 0) AS avg_sale
FROM sales
GROUP BY CustomerType;

SELECT Product, UnitPrice_FCFA,
    CASE WHEN UnitPrice_FCFA > 5000 THEN 'High' ELSE 'Low' END AS band
FROM sales;

